#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: one time Google setup for one app, read only except "Reply to reviews" and gmail.send.
#   scripts/setup_app.sh APP   APP is a short name, e.g. "myapp"; writes config/apps/APP.toml
# Everything it writes lands in the gitignored config/ folder.
# ──────────────────────────────────────────────────────────────────────────

to_unix_path() {
  if command -v cygpath >/dev/null 2>&1; then cygpath -u "$1"; else printf '%s' "$1"; fi
}

move_download() {
  local source dest="$2"
  source=$(to_unix_path "$1")
  [[ -f "$source" ]] || { warn "no file at $source"; return 1; }
  mv "$source" "$dest"
  chmod 600 "$dest"
  printf '  %s✓ moved%s the downloaded file → %s\n' "$GREEN" "$RESET" "$dest"
}

remember_identifier() {
  local value="$1" denylist="config/forbidden.txt"
  [[ -n "$value" ]] || return 0
  touch "$denylist"
  grep -qxF "$value" "$denylist" || printf '%s\n' "$value" >> "$denylist"
}

enable_api() {
  open_url "https://console.cloud.google.com/apis/library/$1?project=$2"
  step "Click Enable. If it already says 'API Enabled', nothing to do."
}

run_wizard() {

cd "$(dirname "$0")/.."
APP="${1:-}"
[[ "$APP" =~ ^[a-z0-9-]+$ ]] || { echo "usage: scripts/setup_app.sh APP   (lowercase letters, digits, dashes)"; exit 2; }
mkdir -p config/apps
APP_CONFIG="config/apps/$APP.toml"
KEY_FILE="config/apps/$APP-service-account.json"
CLIENT_FILE="config/oauth-client.json"
SHARED=1
if [[ -f config/admob-token.json && -f config/gmail-token.json ]]; then
  SHARED=0
  confirm "The shared AdMob and Gmail sign-ins are already set up. Redo them too?" && SHARED=1
fi
TOTAL_STAGES=$(( SHARED ? 10 : 7 ))

banner "Google setup for app '$APP' (read only)"

ENV_FILE="config/apps/$APP.env"

stage "Firebase project and app"
say "Everything for this app lives in its own Firebase project. Note three values."
open_url "https://console.firebase.google.com/"
step "Open the app's project, then the gear icon → Project settings → General."
ask FIREBASE_PROJECT "Project ID (under 'Your project'):"
step "Scroll to 'Your apps', pick the Android app (not a .debug one)."
ask FIREBASE_APP_ID "App ID (looks like 1:123:android:abc):"
ask PACKAGE "Package name:"
write_env FIREBASE_PROJECT "$FIREBASE_PROJECT"
write_env FIREBASE_APP_ID "$FIREBASE_APP_ID"
write_env PACKAGE "$PACKAGE"
remember_identifier "$FIREBASE_PROJECT"
remember_identifier "$FIREBASE_APP_ID"
remember_identifier "$PACKAGE"
pause

stage "Turn on the APIs the report reads"
say "Five tabs open, all in the app's project. Make sure each one is enabled."
enable_api firebasecrashlytics.googleapis.com "$FIREBASE_PROJECT"
enable_api playdeveloperreporting.googleapis.com "$FIREBASE_PROJECT"
enable_api androidpublisher.googleapis.com "$FIREBASE_PROJECT"
enable_api firestore.googleapis.com "$FIREBASE_PROJECT"
enable_api storage.googleapis.com "$FIREBASE_PROJECT"
pause "Press Enter once all five say 'API Enabled'"

stage "Read only service account"
open_url "https://console.cloud.google.com/iam-admin/serviceaccounts/create?project=$FIREBASE_PROJECT"
step "Name: analytics-report. Click 'Create and continue'."
step "Permissions: add the role 'Cloud Datastore Viewer', then add 'Firebase Crashlytics Viewer'."
note "Only these two. No Editor, no Owner, no Admin role."
step "Click Continue, then Done."
step "Copy the account's email from the list (ends in .iam.gserviceaccount.com)."
ask SERVICE_ACCOUNT_EMAIL "Service account email:"
write_env SERVICE_ACCOUNT_EMAIL "$SERVICE_ACCOUNT_EMAIL"
remember_identifier "$SERVICE_ACCOUNT_EMAIL"
pause

stage "Service account key"
if [[ -f "$KEY_FILE" ]] && ! confirm "A key is already saved at $KEY_FILE. Replace it?"; then
  note "Keeping the saved key."
else
  open_url "https://console.cloud.google.com/iam-admin/serviceaccounts?project=$FIREBASE_PROJECT"
  step "Click analytics-report → Keys tab → Add key → Create new key → JSON → Create."
  note "The browser downloads a .json file. Never share it, never commit it."
  until ask DOWNLOADED_KEY "Path of the downloaded .json (drag the file here):" && move_download "${DOWNLOADED_KEY//\"/}" "$KEY_FILE"; do
    warn "Try the path again."
  done
fi
pause

stage "Play Console access"
say "Play grants its own permissions; the Cloud roles don't reach it."
open_url "https://play.google.com/console/developers/users-and-permissions"
step "Invite new users → paste $SERVICE_ACCOUNT_EMAIL"
step "Account permissions: tick only 'View app information and download bulk reports (read only)'."
note "Play's help says bulk reports need this one set account wide."
step "App permissions: Add app → this app → tick only 'Reply to reviews'."
note "The Reviews API refuses service accounts without it. Leave every other box empty."
step "Invite user, then confirm."
warn "Play can take up to a day before the new account can read reports."
pause

stage "Play report bucket and feedback collection"
open_url "https://play.google.com/console/developers/download-reports/reviews"
step "On Download reports → Reviews, click 'Copy Cloud Storage URI'."
note "It looks like gs://pubsite_prod_rev_01234567890987654321/reviews"
ask PLAY_BUCKET_URI "Paste the URI:"
PLAY_BUCKET="${PLAY_BUCKET_URI#gs://}"
PLAY_BUCKET="${PLAY_BUCKET%%/*}"
write_env PLAY_BUCKET "$PLAY_BUCKET"
remember_identifier "$PLAY_BUCKET"
ask FEEDBACK_COLLECTION "Firestore collection holding the app's feedback (e.g. feedback):"
write_env FEEDBACK_COLLECTION "$FEEDBACK_COLLECTION"
cat > "$APP_CONFIG" <<TOML
firebase_project = "$FIREBASE_PROJECT"
firebase_app_id = "$FIREBASE_APP_ID"
package = "$PACKAGE"
play_bucket = "$PLAY_BUCKET"
feedback_collection = "$FEEDBACK_COLLECTION"
service_account_key = "$KEY_FILE"
TOML
printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$APP_CONFIG"
pause

if (( SHARED )); then
  ENV_FILE="config/google.env"
  write_env OAUTH_PROJECT "$FIREBASE_PROJECT"

  stage "Shared: OAuth consent screen"
  say "Two sign-ins shared by every app: one reads AdMob reports, one sends the email."
  say "Their OAuth client lives in this app's project ($OAUTH_PROJECT)."
  open_url "https://console.cloud.google.com/auth/overview?project=$OAUTH_PROJECT"
  step "Get started. App name: Analytics report. Support email: yours. Audience: External."
  step "Contact email: yours. Agree to the policy, Create."
  step "Branding → Application home page: https://github.com/MantasDemenius/analytics-dashboard"
  step "Privacy policy link: https://github.com/MantasDemenius/analytics-dashboard/blob/master/PRIVACY.md"
  step "Authorized domains → Add domain: github.com → Save."
  step "Data access → Add or remove scopes → paste these two into 'Manually add scopes':"
  note "https://www.googleapis.com/auth/admob.report"
  note "https://www.googleapis.com/auth/gmail.send"
  step "Add to table → Update → Save."
  step "Audience → Publish app → Confirm, so the status reads 'In production'."
  warn "In 'Testing' Google expires the sign-in every 7 days and the weekly run fails."
  note "Google won't verify it; that is fine for personal use."
  pause

  stage "Shared: AdMob and Gmail APIs, OAuth client"
  enable_api admob.googleapis.com "$OAUTH_PROJECT"
  enable_api gmail.googleapis.com "$OAUTH_PROJECT"
  open_url "https://console.cloud.google.com/auth/clients/create?project=$OAUTH_PROJECT"
  step "Application type: Desktop app. Name: analytics report. Create."
  step "In the dialog, click Download JSON."
  until ask DOWNLOADED_CLIENT "Path of the downloaded client .json:" && move_download "${DOWNLOADED_CLIENT//\"/}" "$CLIENT_FILE"; do
    warn "Try the path again."
  done
  pause

  stage "Shared: sign in twice"
  say "Two browser sign-ins, one permission each. They may be different Google accounts."
  step "On 'Google hasn't verified this app': Advanced → Go to Analytics report → Continue."
  ask REPORT_RECIPIENT "Email address that should receive the weekly report:"
  write_env REPORT_RECIPIENT "$REPORT_RECIPIENT"
  open_url "https://admob.google.com/v2/settings"
  step "In AdMob (as the account that owns it): Settings → Account information → Publisher ID."
  ask ADMOB_PUBLISHER "Publisher ID (pub-...):"
  write_env ADMOB_PUBLISHER "$ADMOB_PUBLISHER"
  remember_identifier "$ADMOB_PUBLISHER"
  pause "Press Enter, then sign in with the account that OWNS AdMob"
  uv run python scripts/google_login.py admob
  pause "Press Enter, then sign in with the account the report is SENT FROM"
  uv run python scripts/google_login.py gmail
  printf 'recipient = "%s"\nadmob_publisher = "%s"\n' "$REPORT_RECIPIENT" "$ADMOB_PUBLISHER" > config/report.toml
  printf '  %s✓ wrote%s config/report.toml\n' "$GREEN" "$RESET"
  pause
fi

stage "Smoke check"
say "Reads one value from every source. Counts only, no review or feedback text."
if uv run python scripts/smoke_check.py "$APP"; then
  say "Every source answered."
else
  SKIPPED+=("smoke check failures above; re-run: uv run python scripts/smoke_check.py $APP")
  warn "Some checks failed. 'Play report bucket' failing right after the invite is normal;"
  warn "re-run the smoke check tomorrow."
fi
pause

finish
}

run_wizard "$@"; exit
